// bug 6457 接口口径实测：登录 dev 网关后对比 taskCount / todoTaskList / 非v2.0 todoTaskList
const BASE = 'http://unlimited.c.h5.query.mobile.v2.suzhufang.shiqu.suzhou.dev.zhi.com';
const USER = process.env.ZT_TEST_USER || '管理员';
const PASS = process.env.ZT_TEST_PASS || 'zsbase';

async function call(path, { method = 'GET', token, body } = {}) {
  const res = await fetch(BASE + path, {
    method,
    headers: {
      Authorization: token ? `Bearer ${token}` : '',
      'Content-Type': 'application/json;charset=UTF-8',
      project: 'suzhufang',
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let json; try { json = JSON.parse(text); } catch { json = text.slice(0, 300); }
  return { status: res.status, json };
}

const login = await call('/api/v2.0/security/auth/login', { method: 'POST', body: { username: USER, password: PASS } });
console.log('LOGIN status=', login.status);
console.log(JSON.stringify(login.json).slice(0, 400));
const data = login.json?.data ?? login.json;
const token = data?.token || data?.accessToken || data?.access_token;
if (!token) { console.log('NO TOKEN, abort'); process.exit(1); }

const targets = [
  '/api/v2.0/flowable/task/taskCount',
  '/api/v2.0/flowable/task/todoTaskList?pageNum=1&pageSize=1',
  '/api/v2.0/flowable/task/todoTaskList?pageNum=1&pageSize=10',
  '/api/flowable/task/todoTaskList?pageNum=1&pageSize=10',
  '/api/v2.0/flowable/task/todoTaskNum',
];
for (const t of targets) {
  const r = await call(t, { token });
  const j = r.json;
  const summary = typeof j === 'string' ? j
    : JSON.stringify({ code: j.code, msg: j.msg, total: j.total ?? j.data?.total, rowsLen: (j.rows ?? j.data?.rows)?.length, data: typeof j.data === 'object' && !Array.isArray(j.data) && !j.data?.rows ? j.data : undefined }).slice(0, 500);
  console.log(`\n== ${t} -> HTTP ${r.status}`);
  console.log(summary);
}

